// shout_sys: clock domain sys @ 1000000 Hz, generated by Weft from the DAG (66 nodes)
module shout_sys (
  input  wire clk,
  input  wire rst,
  input  wire [0:0] tx_bytes_out_ready,
  input  wire [0:0] rx_bytes_valid,
  input  wire [7:0] rx_bytes_data,
  input  wire [0:0] pin_uart_rx,
  output wire [0:0] x_4,
  output wire [7:0] x_7,
  output wire [0:0] x_10,
  output wire [0:0] x_73
);
  wire [0:0] tx_bytes_valid;  // probe
  wire [0:0] tx_bytes_ready;  // probe
  wire [0:0] tx_bytes_out_valid;  // probe
  wire [7:0] tx_bytes_data;  // probe
  wire [7:0] tx_bytes_out_data;  // probe
  wire [0:0] rx_bytes_out_ready;  // probe
  wire [0:0] rx_bytes_ready;  // probe
  wire [0:0] rx_bytes_out_valid;  // probe
  wire [7:0] rx_bytes_out_data;  // probe
  wire [0:0] upcase_on_rx_bytes_ready;  // probe
  wire [6:0] n16 = 7'h61;
  wire [0:0] n17;
  wire [6:0] n20 = 7'h7A;
  wire [0:0] n21;
  wire [0:0] n22;
  wire [5:0] n25 = 6'h20;
  wire [7:0] n26;
  wire [7:0] n30;
  reg [0:0] tx_bytes_main_valid = 1'h0;
  reg [7:0] tx_bytes_main = 8'h0;
  reg [0:0] tx_bytes_skid_valid = 1'h0;
  reg [7:0] tx_bytes_skid = 8'h0;
  wire [0:0] n35;
  wire [0:0] n36;
  wire [0:0] n37;
  wire [0:0] n38;
  wire [0:0] n39;
  wire [0:0] n40;
  wire [0:0] n41;
  wire [0:0] n42;
  wire [0:0] n43;
  wire [0:0] n44;
  wire [7:0] n45;
  wire [7:0] n46;
  wire [0:0] n47 = 1'h0;
  wire [0:0] n48;
  wire [0:0] n49;
  wire [0:0] n50;
  wire [7:0] n51;
  reg [0:0] rx_bytes_main_valid = 1'h0;
  reg [7:0] rx_bytes_main = 8'h0;
  reg [0:0] rx_bytes_skid_valid = 1'h0;
  reg [7:0] rx_bytes_skid = 8'h0;
  wire [0:0] n56;
  wire [0:0] n57;
  wire [0:0] n58;
  wire [0:0] n59;
  wire [0:0] n60;
  wire [0:0] n61;
  wire [0:0] n62;
  wire [0:0] n63;
  wire [0:0] n64;
  wire [0:0] n65;
  wire [7:0] n66;
  wire [7:0] n67;
  wire [0:0] n68 = 1'h0;
  wire [0:0] n69;
  wire [0:0] n70;
  wire [0:0] n71;
  wire [7:0] n72;
  assign tx_bytes_valid = rx_bytes_out_valid;
  assign tx_bytes_ready = n35;
  assign tx_bytes_out_valid = tx_bytes_main_valid;
  assign tx_bytes_data = n30;
  assign tx_bytes_out_data = tx_bytes_main;
  assign rx_bytes_out_ready = upcase_on_rx_bytes_ready;
  assign rx_bytes_ready = n56;
  assign rx_bytes_out_valid = rx_bytes_main_valid;
  assign rx_bytes_out_data = rx_bytes_main;
  assign upcase_on_rx_bytes_ready = tx_bytes_ready;
  assign n17 = rx_bytes_out_data >= {{1{1'b0}}, n16};  // c >= 97 (line 14)
  assign n21 = rx_bytes_out_data <= {{1{1'b0}}, n20};  // c <= 122 (line 14)
  assign n22 = (|n17) && (|n21);  // c >= 97 && c <= 122 (line 14)
  assign n26 = rx_bytes_out_data ^ {{2{1'b0}}, n25};  // c ^ 0x20 (line 14)
  assign n30 = (|n22) ? n26 : rx_bytes_out_data;  // c >= 97 && c <= 122 ? c ^ 0x20 : c (line 14)
  assign n35 = !(|tx_bytes_skid_valid);
  assign n36 = (|tx_bytes_valid) && (|n35);
  assign n37 = (|tx_bytes_main_valid) && (|tx_bytes_out_ready);
  assign n38 = !(|tx_bytes_main_valid);
  assign n39 = (|n37) || (|n38);
  assign n40 = (|tx_bytes_skid_valid) || (|n36);
  assign n41 = (|n39) ? n40 : tx_bytes_main_valid;
  assign n42 = (|n35) && (|n36);
  assign n43 = (|n39) && (|n42);
  assign n44 = (|n39) && (|tx_bytes_skid_valid);
  assign n45 = (|n44) ? tx_bytes_skid : tx_bytes_main;
  assign n46 = (|n43) ? tx_bytes_data : n45;
  assign n48 = (|n39) ? n47 : n40;
  assign n49 = !(|n39);
  assign n50 = (|n49) && (|n36);
  assign n51 = (|n50) ? tx_bytes_data : tx_bytes_skid;
  assign n56 = !(|rx_bytes_skid_valid);
  assign n57 = (|rx_bytes_valid) && (|n56);
  assign n58 = (|rx_bytes_main_valid) && (|rx_bytes_out_ready);
  assign n59 = !(|rx_bytes_main_valid);
  assign n60 = (|n58) || (|n59);
  assign n61 = (|rx_bytes_skid_valid) || (|n57);
  assign n62 = (|n60) ? n61 : rx_bytes_main_valid;
  assign n63 = (|n56) && (|n57);
  assign n64 = (|n60) && (|n63);
  assign n65 = (|n60) && (|rx_bytes_skid_valid);
  assign n66 = (|n65) ? rx_bytes_skid : rx_bytes_main;
  assign n67 = (|n64) ? rx_bytes_data : n66;
  assign n69 = (|n60) ? n68 : n61;
  assign n70 = !(|n60);
  assign n71 = (|n70) && (|n57);
  assign n72 = (|n71) ? rx_bytes_data : rx_bytes_skid;
  assign x_4 = tx_bytes_out_valid;
  assign x_7 = tx_bytes_out_data;
  assign x_10 = rx_bytes_ready;
  assign x_73 = pin_uart_rx;
  always @(posedge clk) begin
    tx_bytes_main_valid <= rst ? 1'h0 : n41;
    tx_bytes_main <= rst ? 8'h0 : n46;
    tx_bytes_skid_valid <= rst ? 1'h0 : n48;
    tx_bytes_skid <= rst ? 8'h0 : n51;
    rx_bytes_main_valid <= rst ? 1'h0 : n62;
    rx_bytes_main <= rst ? 8'h0 : n67;
    rx_bytes_skid_valid <= rst ? 1'h0 : n69;
    rx_bytes_skid <= rst ? 8'h0 : n72;
  end
endmodule

// Native cells used by this design. In the Lab their behaviour is JavaScript. A cell with a hand-written core
// (hdl/cells, added by weft build) gets an adapter from the design's stream signals to the core's ports; any
// other cell is a black box with the interface the design uses.

// uart-rx cell → weft_core_uart_rx
module weft_uart_rx #(parameter BAUD = 0, parameter CLK_HZ = 0) (
  input  wire clk,
  input  wire rst,
  input  wire [0:0] rx,
  output wire [7:0] rx_bytes_data,
  input  wire [0:0] rx_bytes_ready,
  output wire [0:0] rx_bytes_valid
);
  weft_core_uart_rx #(.BAUD(BAUD), .CLK_HZ(CLK_HZ)) core (
    .clk(clk),
    .rst(rst),
    .rx(rx),
    .m_valid(rx_bytes_valid),
    .m_data(rx_bytes_data[7:0]),
    .m_ready(rx_bytes_ready)
  );
endmodule

// uart-tx cell → weft_core_uart_tx
module weft_uart_tx #(parameter BAUD = 0, parameter CLK_HZ = 0) (
  input  wire clk,
  input  wire rst,
  input  wire [7:0] tx_bytes_data,
  output wire [0:0] tx_bytes_ready,
  input  wire [0:0] tx_bytes_valid,
  output wire [0:0] tx
);
  weft_core_uart_tx #(.BAUD(BAUD), .CLK_HZ(CLK_HZ)) core (
    .clk(clk),
    .rst(rst),
    .s_valid(tx_bytes_valid),
    .s_data(tx_bytes_data[7:0]),
    .s_ready(tx_bytes_ready),
    .tx(tx)
  );
endmodule

// shout: top level generated by Weft — 1 clock domain, 2 native cells
// Clocks are top-level inputs (PLL primitives are not emitted); rst is synchronous and active high.
module shout (
  input  wire [0:0] clk_sys,
  input  wire [0:0] rst,
  input  wire [0:0] uart_rx,
  output wire [0:0] uart_tx
);
  wire [0:0] sys__tx_bytes_out_ready;
  wire [0:0] sys__rx_bytes_valid;
  wire [7:0] sys__rx_bytes_data;
  wire [0:0] sys__pin_uart_rx;
  wire [0:0] sys__x_4;
  wire [7:0] sys__x_7;
  wire [0:0] sys__x_10;
  wire [0:0] sys__x_73;
  assign sys__pin_uart_rx[0] = uart_rx;
  shout_sys u_sys (
    .clk(clk_sys),
    .rst(rst),
    .tx_bytes_out_ready(sys__tx_bytes_out_ready),
    .rx_bytes_valid(sys__rx_bytes_valid),
    .rx_bytes_data(sys__rx_bytes_data),
    .pin_uart_rx(sys__pin_uart_rx),
    .x_4(sys__x_4),
    .x_7(sys__x_7),
    .x_10(sys__x_10),
    .x_73(sys__x_73)
  );
  weft_uart_rx #(.BAUD(115200), .CLK_HZ(1000000)) u_rx (
    .clk(clk_sys),
    .rst(rst),
    .rx(sys__x_73),
    .rx_bytes_data(sys__rx_bytes_data),
    .rx_bytes_ready(sys__x_10),
    .rx_bytes_valid(sys__rx_bytes_valid)
  );  // native cell rx (uart-rx): adapter to weft_core_uart_rx (hdl/cells)
  weft_uart_tx #(.BAUD(115200), .CLK_HZ(1000000)) u_tx (
    .clk(clk_sys),
    .rst(rst),
    .tx_bytes_data(sys__x_7),
    .tx_bytes_ready(sys__tx_bytes_out_ready),
    .tx_bytes_valid(sys__x_4),
    .tx(uart_tx)
  );  // native cell tx (uart-tx): adapter to weft_core_uart_tx (hdl/cells)
endmodule
